-- apicc 元数据 H2 库初始化脚本（规格 m3 §2 D5/D6）。
-- 约束：
--   1. 全部使用幂等 DDL（CREATE TABLE IF NOT EXISTS），配合 spring.sql.init.mode=always 每次启动执行；
--   2. SQL 保持可移植子集（避免 H2 专有语法，未来可换 Postgres）；
--   3. 主键取型（裁定 A，规格 2026-09-09 BIGINT 化）：实体主键为 BIGINT——
--      GENERATED BY DEFAULT AS IDENTITY（默认数据库自增；BY DEFAULT 容外部策略显式携 id 插入）；
--      对外 JSON/URL 一律字符串化数字（Java 全链 Long，View 层 String.valueOf 出参）；
--      关联表用自然复合主键（tokens/memberships/project_acl/file_versions），
--      其中的实体引用列（workspace_id/project_id/group_id 等）同为 BIGINT（批 3 任务 3 收口）；
--   4. 时间戳列（裁定 B）：一律 TIMESTAMP WITH TIME ZONE 存绝对时刻，写入统一经 OffsetDateTime(UTC)，
--      读取以 OffsetDateTime → Instant 还原；API 序列化形状（ISO-8601 UTC）由任务 3-5 契约测试钉住；
--   5. 角色列：VARCHAR + CHECK IN（可移植写法），枚举外脏值在库层拦下；
--   6. 未发布阶段（规格 §8）表结构变更不做迁移：旧库启动若因结构不符报错（未知列等），
--      删库重开（删 server-data）即可，生产化前的破坏性变更均走此口径。

-- 账号（规格 §3.1：bcrypt 哈希入库，服务端不存明文密码；§2：role/disabled 支撑账号管家）
CREATE TABLE IF NOT EXISTS users (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY,
    username      VARCHAR(32)  NOT NULL,
    password_hash VARCHAR(100) NOT NULL,
    display_name  VARCHAR(64)  NOT NULL,
    role          VARCHAR(16)  NOT NULL DEFAULT 'USER',
    disabled      BOOLEAN      NOT NULL DEFAULT FALSE,
    created_at    TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT pk_users PRIMARY KEY (id),
    CONSTRAINT uk_users_username UNIQUE (username),
    CONSTRAINT ck_users_role CHECK (role IN ('USER','SUPERADMIN'))
);

-- 认证令牌（规格 §2 D4：不透明 Bearer token，仅存 SHA-256 哈希；token_hash 即自然主键）
CREATE TABLE IF NOT EXISTS tokens (
    token_hash VARCHAR(64)  NOT NULL,
    user_id    BIGINT       NOT NULL,
    expires_at TIMESTAMP WITH TIME ZONE NOT NULL,
    revoked    BOOLEAN      NOT NULL DEFAULT FALSE,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT pk_tokens PRIMARY KEY (token_hash)
);

-- 团队工作区（规格 §3.2；内容随 file_versions.content 入库，规格 §5——磁盘内容树已退役）
-- 规格 2026-09-08 §1：首启自动建唯一「默认工作区」；name 全局唯一（并发安全靠唯一约束）
CREATE TABLE IF NOT EXISTS workspaces (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY,
    name       VARCHAR(64) NOT NULL,
    created_by BIGINT      NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT pk_workspaces PRIMARY KEY (id),
    CONSTRAINT uk_workspaces_name UNIQUE (name)
);

-- 工作区成员角色（规格 §2 D5 第一层：OWNER > ADMIN > EDITOR > VIEWER）
CREATE TABLE IF NOT EXISTS memberships (
    workspace_id BIGINT      NOT NULL,
    user_id      BIGINT      NOT NULL,
    role         VARCHAR(16) NOT NULL CHECK (role IN ('OWNER','ADMIN','EDITOR','VIEWER')),
    created_at   TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT pk_memberships PRIMARY KEY (workspace_id, user_id)
);

-- 项目级 ACL 覆盖（规格 §2 D5 第二层：NONE/VIEWER/EDITOR/ADMIN；无行 = 继承工作区角色）
CREATE TABLE IF NOT EXISTS project_acl (
    workspace_id BIGINT      NOT NULL,
    project_id   BIGINT      NOT NULL,
    user_id      BIGINT      NOT NULL,
    role         VARCHAR(16) NOT NULL CHECK (role IN ('NONE','VIEWER','EDITOR','ADMIN')),
    updated_at   TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT pk_project_acl PRIMARY KEY (workspace_id, project_id, user_id)
);

-- 文件版本行 = 元数据 + 内容正文（规格 §2 D6 + §5：每 (workspace, path) 一份；version 从 1 起，
-- 乐观并发以 UPDATE ... WHERE version = ? 单条 SQL 原子递增；version 仅供并发比对，不追溯历史）
CREATE TABLE IF NOT EXISTS file_versions (
    workspace_id BIGINT       NOT NULL,
    path         VARCHAR(512) NOT NULL,
    content_hash VARCHAR(64)  NOT NULL,
    version      BIGINT       NOT NULL,
    updated_by   BIGINT       NOT NULL,
    updated_at   TIMESTAMP WITH TIME ZONE NOT NULL,
    content      CLOB,
    CONSTRAINT pk_file_versions PRIMARY KEY (workspace_id, path),
    CONSTRAINT ck_file_versions_version CHECK (version >= 1)
);

-- 分组（规格 2026-09-08 §4）：同工作区内名称唯一；默认分组 name='默认分组' 不可删改
CREATE TABLE IF NOT EXISTS groups (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY,
    workspace_id BIGINT      NOT NULL,
    name         VARCHAR(64) NOT NULL,
    is_default   BOOLEAN     NOT NULL DEFAULT FALSE,
    created_at   TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT pk_groups PRIMARY KEY (id),
    CONSTRAINT uk_groups_ws_name UNIQUE (workspace_id, name)
);

-- 项目（规格 §4）：允许同名（身份=id）；挂分组；内容树按项目挂载
CREATE TABLE IF NOT EXISTS projects (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY,
    workspace_id BIGINT      NOT NULL,
    group_id     BIGINT      NOT NULL,
    name         VARCHAR(64) NOT NULL,
    created_at   TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT pk_projects PRIMARY KEY (id),
    CONSTRAINT fk_projects_group FOREIGN KEY (group_id) REFERENCES groups(id)
);

-- groups 增默认分组标记（seeder/create 落 TRUE；改名/删除守卫判据）
-- ALTER 仅服务既有库兼容（新库 CREATE TABLE 已含 is_default；未发布阶段口径=删库重开，此处双保险）
ALTER TABLE groups ADD COLUMN IF NOT EXISTS is_default BOOLEAN NOT NULL DEFAULT FALSE;

-- file_versions 扩内容列（规格 §5 内容入库）：一行 = 元数据 + 字节（CLOB/PG text）
-- ALTER 形态（幂等：H2 支持 ADD COLUMN IF NOT EXISTS；新库走 CREATE TABLE 已含）：
ALTER TABLE file_versions ADD COLUMN IF NOT EXISTS content CLOB;

-- Explicit publication only; existing rows retain their original bytes.
ALTER TABLE projects ADD COLUMN IF NOT EXISTS asset_format VARCHAR(32);
ALTER TABLE projects ADD COLUMN IF NOT EXISTS contract_project_id VARCHAR(36);
ALTER TABLE projects ADD COLUMN IF NOT EXISTS asset_version BIGINT NOT NULL DEFAULT 0;

-- No update operation: immutable definition bytes survive subsequent source edits/deletes.
CREATE TABLE IF NOT EXISTS execution_snapshots (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    workspace_id BIGINT NOT NULL,
    project_id BIGINT NOT NULL,
    created_by BIGINT NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL,
    assets_json CLOB NOT NULL,
    CONSTRAINT pk_execution_snapshots PRIMARY KEY (id)
);

-- Agent identities are separate from users and from project execution authorization.
CREATE TABLE IF NOT EXISTS execution_agents (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name VARCHAR(128) NOT NULL,
    accepting_jobs BOOLEAN NOT NULL DEFAULT TRUE,
    revoked BOOLEAN NOT NULL DEFAULT FALSE,
    identity_hash VARCHAR(64),
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS execution_agent_enrollments (
    token_hash VARCHAR(64) PRIMARY KEY, agent_id BIGINT NOT NULL, created_by BIGINT NOT NULL,
    expires_at TIMESTAMP WITH TIME ZONE NOT NULL, used_at TIMESTAMP WITH TIME ZONE
);
CREATE TABLE IF NOT EXISTS execution_agent_workspace_grants (
    agent_id BIGINT NOT NULL, workspace_id BIGINT NOT NULL, PRIMARY KEY(agent_id,workspace_id)
);
CREATE TABLE IF NOT EXISTS execution_agent_project_allocations (
    agent_id BIGINT NOT NULL, workspace_id BIGINT NOT NULL, project_id BIGINT NOT NULL, PRIMARY KEY(agent_id,project_id)
);
CREATE TABLE IF NOT EXISTS execution_project_agents (
    project_id BIGINT NOT NULL, agent_id BIGINT NOT NULL, PRIMARY KEY(project_id,agent_id)
);
CREATE TABLE IF NOT EXISTS execution_project_settings (
    project_id BIGINT PRIMARY KEY, default_agent_id BIGINT
);
CREATE TABLE IF NOT EXISTS execution_configs (
    scope_type VARCHAR(16) NOT NULL, scope_id BIGINT NOT NULL, version BIGINT NOT NULL DEFAULT 0,
    config_json CLOB NOT NULL, applied_version BIGINT NOT NULL DEFAULT 0,
    pending_fields_json CLOB NOT NULL DEFAULT '[]', restart_fields_json CLOB NOT NULL DEFAULT '[]',
    PRIMARY KEY(scope_type,scope_id)
);
CREATE TABLE IF NOT EXISTS execution_script_grants (
    agent_id BIGINT NOT NULL, workspace_id BIGINT NOT NULL, project_id BIGINT NOT NULL,
    version BIGINT NOT NULL, grant_scope VARCHAR(32) NOT NULL, scripts_json CLOB NOT NULL,
    granted_by BIGINT NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL,
    PRIMARY KEY(agent_id,project_id)
);
CREATE TABLE IF NOT EXISTS execution_management_audit (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, actor_id BIGINT NOT NULL,
    action VARCHAR(64) NOT NULL, scope_type VARCHAR(16) NOT NULL, scope_id BIGINT NOT NULL,
    version BIGINT, agent_id BIGINT, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP
);
-- Historical rows have no recoverable target; do not invent one when extending an existing database.
ALTER TABLE execution_management_audit ADD COLUMN IF NOT EXISTS agent_id BIGINT;
-- One persistent monotonic policy revision avoids collisions between inherited layers.
CREATE TABLE IF NOT EXISTS execution_policy_revision (id BIGINT PRIMARY KEY, version BIGINT NOT NULL);
INSERT INTO execution_policy_revision(id,version) SELECT 1,0 WHERE NOT EXISTS (SELECT 1 FROM execution_policy_revision WHERE id=1);
-- Persist deployment defaults separately: restarting with new defaults must invalidate stale application claims.
CREATE TABLE IF NOT EXISTS execution_deployment_defaults (
    id BIGINT PRIMARY KEY,
    agent_json CLOB NOT NULL,
    policy_json CLOB NOT NULL,
    deployment_json CLOB NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS uk_execution_agent_identity ON execution_agents(identity_hash);

-- Credential envelopes only; the deployment master key is never stored in this database.
-- Tombstones keep monotonic versions across delete/recreate and prevent stale preparation reuse.
CREATE TABLE IF NOT EXISTS execution_project_credentials (
    workspace_id BIGINT NOT NULL, project_id BIGINT NOT NULL, ref_id VARCHAR(256) NOT NULL,
    version BIGINT NOT NULL, key_id VARCHAR(128), nonce BINARY VARYING, ciphertext BINARY VARYING,
    PRIMARY KEY(workspace_id,project_id,ref_id)
);
CREATE TABLE IF NOT EXISTS execution_project_attachments (
    workspace_id BIGINT NOT NULL, project_id BIGINT NOT NULL, ref_id VARCHAR(256) NOT NULL,
    version BIGINT NOT NULL, kind VARCHAR(32) NOT NULL, hash VARCHAR(64) NOT NULL,
    size BIGINT NOT NULL, content BINARY LARGE OBJECT,
    PRIMARY KEY(workspace_id,project_id,ref_id)
);
ALTER TABLE execution_project_credentials ADD CONSTRAINT IF NOT EXISTS fk_execution_credentials_project
    FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE;
ALTER TABLE execution_project_attachments ADD CONSTRAINT IF NOT EXISTS fk_execution_attachments_project
    FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE;

-- One authoritative job/execution assignment; reports and release evidence are independent.
CREATE TABLE IF NOT EXISTS execution_jobs (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    execution_id BIGINT NOT NULL UNIQUE,
    workspace_id BIGINT NOT NULL, project_id BIGINT NOT NULL, submitted_by BIGINT NOT NULL,
    agent_id BIGINT NOT NULL, snapshot_id BIGINT NOT NULL, intent_id VARCHAR(512) NOT NULL,
    intent_hash VARCHAR(64) NOT NULL, submission_json CLOB NOT NULL, task_json CLOB NOT NULL,
    inputs_json CLOB NOT NULL, inputs_digest VARCHAR(64) NOT NULL,
    state VARCHAR(16) NOT NULL DEFAULT 'queued', accepted BOOLEAN NOT NULL DEFAULT FALSE,
    cancel_state VARCHAR(16) NOT NULL DEFAULT 'none', execution_released BOOLEAN NOT NULL DEFAULT FALSE,
    permit_id BIGINT, permit_json CLOB, progress_sequence BIGINT NOT NULL DEFAULT 0, progress_json CLOB,
    summary_json CLOB, report_hash VARCHAR(64), report_bytes BIGINT, report_content BINARY LARGE OBJECT,
    reserved_input_bytes BIGINT NOT NULL DEFAULT 0, reserved_result_bytes BIGINT NOT NULL DEFAULT 0,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    queue_expires_at TIMESTAMP WITH TIME ZONE,
    UNIQUE(submitted_by,project_id,intent_id)
);
CREATE TABLE IF NOT EXISTS execution_job_messages (
    agent_id BIGINT NOT NULL, message_id VARCHAR(512) NOT NULL, payload_hash VARCHAR(64) NOT NULL,
    job_id BIGINT NOT NULL, execution_id BIGINT NOT NULL, PRIMARY KEY(agent_id,message_id)
);
CREATE TABLE IF NOT EXISTS execution_stress_reservations (
    job_id BIGINT PRIMARY KEY REFERENCES execution_jobs(id) ON DELETE CASCADE,
    agent_id BIGINT NOT NULL, jobs BIGINT NOT NULL, processes BIGINT NOT NULL, vus BIGINT NOT NULL,
    request_concurrency BIGINT NOT NULL, max_rps DOUBLE PRECISION NOT NULL, metric_memory_bytes BIGINT NOT NULL
);
CREATE INDEX IF NOT EXISTS execution_stress_agent ON execution_stress_reservations(agent_id);
ALTER TABLE execution_jobs ADD COLUMN IF NOT EXISTS capacity_wait_reason VARCHAR(64);
ALTER TABLE execution_jobs ADD COLUMN IF NOT EXISTS stress_metadata_json CLOB;
ALTER TABLE execution_jobs ADD COLUMN IF NOT EXISTS report_kind VARCHAR(32);
ALTER TABLE execution_jobs ADD COLUMN IF NOT EXISTS report_verdict VARCHAR(32);
CREATE TABLE IF NOT EXISTS execution_job_outbox (
    message_id VARCHAR(512) PRIMARY KEY, agent_id BIGINT NOT NULL, job_id BIGINT,
    execution_id BIGINT, kind VARCHAR(32) NOT NULL, payload_json CLOB NOT NULL,
    acknowledged BOOLEAN NOT NULL DEFAULT FALSE
);
CREATE TABLE IF NOT EXISTS execution_job_ids (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY);
CREATE TABLE IF NOT EXISTS execution_debug_sessions (
    handle VARCHAR(128) PRIMARY KEY, workspace_id BIGINT NOT NULL, project_id BIGINT NOT NULL,
    owner_id BIGINT NOT NULL, agent_id BIGINT NOT NULL, expires_at TIMESTAMP WITH TIME ZONE NOT NULL
);
CREATE TABLE IF NOT EXISTS execution_agent_control_state (
    agent_id BIGINT PRIMARY KEY, session_id VARCHAR(512) NOT NULL,
    applied_config_version VARCHAR(32) NOT NULL,
    last_seen TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS execution_agent_runtime (
    agent_id BIGINT PRIMARY KEY, session_id VARCHAR(512) NOT NULL, description_json CLOB NOT NULL
);
ALTER TABLE execution_debug_sessions ADD COLUMN IF NOT EXISTS host_session_id VARCHAR(512);
ALTER TABLE execution_debug_sessions ADD COLUMN IF NOT EXISTS server_id VARCHAR(2048);
ALTER TABLE execution_jobs ADD COLUMN IF NOT EXISTS runtime_session_id VARCHAR(512);
-- Result transfer is independent of execution release; no hash is not proof of no pending result.
ALTER TABLE execution_jobs ADD COLUMN IF NOT EXISTS report_state VARCHAR(16) NOT NULL DEFAULT 'none';
-- Unknown historical archive times are conservatively anchored by the bounded cleanup consumer.
ALTER TABLE execution_jobs ADD COLUMN IF NOT EXISTS report_retained_at TIMESTAMP WITH TIME ZONE;
CREATE INDEX IF NOT EXISTS execution_result_retention ON execution_jobs(report_state,project_id,report_retained_at);
UPDATE execution_jobs SET report_state='archived' WHERE report_content IS NOT NULL AND report_state<>'archived';
UPDATE execution_jobs SET report_state='pending' WHERE report_content IS NULL AND report_state='none'
    AND (state IN ('preparing','running') OR report_hash IS NOT NULL);
